UPDATE t_score_dimension
SET dimension_code = CASE id
    WHEN #{item.id} THEN #{item.dimensionCode}
    END,
    dimension_name = CASE id
    WHEN #{item.id} THEN #{item.dimensionName}
    END,
    sort_no = CASE id
    WHEN #{item.id} THEN #{item.sortNo}
    END
WHERE deleted = 0 AND id IN
#{item.id}
